        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int r = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        int[][] grid = new int[r][c];
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                in.nextToken();
                grid[i][j] = (int) in.nval;
            }
        List<String> paths = allPaths(grid);
        StringBuilder sb = new StringBuilder();
        sb.append(paths.size()).append('\n');
        for (String p : paths) sb.append(p).append('\n');
        System.out.print(sb);
